<style>:root{--ink:#20251f;--muted:#687066;--paper:#fffdf9;--cream:#f3efe7;--green:#52664d;--line:#ded8cd;--gold:#b68b43}*{box-sizing:border-box}html,body{margin:0;height:100%;background:var(--cream);color:var(--ink);font-family:'DM Sans',sans-serif}h1,h2,h3,h4{font-family:'Playfair Display',serif}.top{height:68px;background:rgba(255,253,249,.96);backdrop-filter:blur(12px);border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 24px;position:relative;z-index:20}.brand{font-weight:800;letter-spacing:.1em;font-size:.8rem}.brand span{display:inline-grid;place-items:center;width:40px;height:40px;border:1px solid var(--ink);margin-right:9px;font-family:'Playfair Display';font-size:13px}.navlinks{display:flex;align-items:center;gap:20px}.navlinks a{color:#4f574f;font-weight:700;font-size:13px}.navlinks .active{color:var(--green)}.tools{display:flex;gap:7px;flex-wrap:wrap}.btnx{border:1px solid #cfc8bb;background:#fff;padding:9px 12px;font-weight:700;font-size:12px}.btnx.primary{background:var(--green);color:#fff;border-color:var(--green)}.workspace{height:calc(100vh - 68px);display:grid;grid-template-columns:285px 1fr 300px;min-height:600px}.side{background:rgba(255,253,249,.96);overflow:auto;padding:20px;border-right:1px solid var(--line);z-index:5}.right{border-right:0;border-left:1px solid var(--line)}.map{position:relative;min-width:0}.mapbox{position:absolute;inset:0}.section-label{font-size:.67rem;text-transform:uppercase;letter-spacing:.15em;font-weight:800;color:var(--green)}.metric{font-family:'Playfair Display';font-size:28px;font-weight:600}.muted{font-size:12px;color:var(--muted);line-height:1.65}.status{padding:10px 0;font-size:12px;border-bottom:1px solid var(--line)}.coord{font-family:monospace;font-size:11px;word-break:break-all;color:#687066;margin-top:10px}.legend{display:flex;gap:8px;align-items:center;font-size:12px;margin:8px 0}.dot{width:10px;height:10px;background:var(--green);display:inline-block}.dot.blue{background:#3478b8}.dot.gold{background:var(--gold)}.map-hint{position:absolute;left:20px;top:20px;background:rgba(255,253,249,.95);padding:14px 16px;box-shadow:0 10px 35px rgba(0,0,0,.14);z-index:4;max-width:390px;font-size:12px;border-left:3px solid var(--green)}.mode{font-weight:800}.table-mini{width:100%;font-size:11px}.table-mini td{padding:5px 2px;border-bottom:1px solid #eee}.canvas2d{width:100%;height:230px;border:1px solid var(--line);background:#faf9f5}.feature{padding:13px 0;border-bottom:1px solid var(--line)}.feature strong{display:block;font-size:13px}.badge-soft{background:#edf1eb;padding:4px 7px;font-size:10px;font-weight:700}.footer-note{font-size:10px;color:#7b8278;margin-top:12px;line-height:1.6}.maplibregl-ctrl-group{border:0!important;box-shadow:0 8px 25px #0002!important}.maplibregl-ctrl-group button{background:#fffdf9!important}@media(max-width:1150px){.workspace{grid-template-columns:250px 1fr}.right{display:none}}@media(max-width:780px){.top{height:auto;min-height:68px;align-items:flex-start;padding:12px 15px;gap:10px;flex-direction:column}.navlinks{display:none}.workspace{height:calc(100vh - 115px);grid-template-columns:1fr}.side{display:none}.map-hint{max-width:280px;left:12px;top:12px}.tools{width:100%}.tools .btnx{flex:1}}</style></head>
