<script src="https://unpkg.com/maplibre-gl@5.6.1/dist/maplibre-gl.js"></script><script>const map=new maplibregl.Map({container:'map',style:{version:8,sources:{osm:{type:'raster',tiles:['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],tileSize:256,attribution:'© OpenStreetMap contributors'}},layers:[{id:'osm',type:'raster',source:'osm'}]},center:[34.8,-6.16],zoom:6});map.addControl(new maplibregl.NavigationControl(),'top-right');let drawing=false,points=[],finished=false;const sourceId='plot-source';function refresh(){const feats=[];if(points.length>1)feats.push({type:'Feature',properties:{},geometry:{type:'LineString',coordinates:points}});if(points.length>=3&&finished)feats.push({type:'Feature',properties:{kind:'plot'},geometry:{type:'Polygon',coordinates:[[...points,points[0]]]}});const s=map.getSource(sourceId);if(s)s.setData({type:'FeatureCollection',features:feats});points.forEach((p,i)=>{if(!map.getSource('p'+i)){map.addSource('p'+i,{type:'geojson',data:{type:'Feature',properties:{},geometry:{type:'Point',coordinates:p}}});map.addLayer({id:'p'+i,type:'circle',source:'p'+i,paint:{'circle-radius':5,'circle-color':'#b68b43','circle-stroke-color':'#fff','circle-stroke-width':2}})}else map.getSource('p'+i).setData({type:'Feature',properties:{},geometry:{type:'Point',coordinates:p}})});if(points.length>=3&&finished){let a=0,p=0;for(let i=0;i<points.length;i++){let j=(i+1)%points.length;let[lon1,lat1]=points[i],[lon2,lat2]=points[j];let dx=(lon2-lon1)*111320*Math.cos((lat1+lat2)*Math.PI/360),dy=(lat2-lat1)*110540;p+=Math.hypot(dx,dy);a+=lon1*lat2-lon2*lat1}a=Math.abs(a)/2*111320*110540*Math.cos((points.reduce((s,x)=>s+x[1],0)/points.length)*Math.PI/180);document.getElementById('area').textContent=a.toFixed(2)+' m²';document.getElementById('perimeter').textContent=p.toFixed(2)+' m';draw2d()}else{document.getElementById('area').textContent='0.00 m²';document.getElementById('perimeter').textContent='0.00 m';draw2d()}document.getElementById('points').innerHTML=points.length?points.map((p,i)=>`<tr><td>P${i+1}</td><td>${p[1].toFixed(6)}</td><td>${p[0].toFixed(6)}</td></tr>`).join(''):'<tr><td class="muted">No points yet.</td></tr>'}function finish(){if(points.length<3){alert('Add at least 3 boundary points.');return}finished=true;drawing=false;document.getElementById('modeText').textContent='Plot completed.';refresh();save()}function save(){localStorage.setItem('ramani-majengo-plot',JSON.stringify(points))}function draw2d(){const c=document.getElementById('plan2d'),x=c.getContext('2d');x.clearRect(0,0,c.width,c.height);x.fillStyle='#faf9f5';x.fillRect(0,0,c.width,c.height);if(!points.length)return;let xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys),pad=35,s=Math.min((c.width-pad*2)/Math.max(maxx-minx,.000001),(c.height-pad*2)/Math.max(maxy-miny,.000001)),xy=p=>[pad+(p[0]-minx)*s,c.height-pad-(p[1]-miny)*s];x.beginPath();points.forEach((p,i)=>{let q=xy(p);i?x.lineTo(q[0],q[1]):x.moveTo(q[0],q[1])});if(finished)x.closePath();x.fillStyle='#e7eee3';x.fill();x.strokeStyle='#52664d';x.lineWidth=3;x.stroke();points.forEach((p,i)=>{let q=xy(p);x.fillStyle='#b68b43';x.beginPath();x.arc(q[0],q[1],5,0,Math.PI*2);x.fill();x.fillStyle='#20251f';x.font='11px Arial';x.fillText('P'+(i+1),q[0]+7,q[1]-7)})}map.on('load',()=>{map.addSource(sourceId,{type:'geojson',data:{type:'FeatureCollection',features:[]}});map.addLayer({id:'plot-fill',type:'fill',source:sourceId,filter:['==','$type','Polygon'],paint:{'fill-color':'#52664d','fill-opacity':.22}});map.addLayer({id:'plot-line',type:'line',source:sourceId,paint:{'line-color':'#52664d','line-width':3}});try{points=JSON.parse(localStorage.getItem('ramani-majengo-plot')||'[]');if(points.length>=3)finished=true}catch(e){}refresh()});map.on('click',e=>{if(!drawing)return;points.push([e.lngLat.lng,e.lngLat.lat]);finished=false;document.getElementById('modeText').textContent='Point '+points.length+' added — keep drawing or Finish.';refresh()});map.on('dblclick',e=>{e.preventDefault();if(drawing)finish()});map.on('mousemove',e=>document.getElementById('cursor').textContent=e.lngLat.lat.toFixed(6)+', '+e.lngLat.lng.toFixed(6));document.getElementById('drawBtn').onclick=()=>{drawing=true;finished=false;points=[];for(let i=0;i<80;i++){if(map.getLayer('p'+i))map.removeLayer('p'+i);if(map.getSource('p'+i))map.removeSource('p'+i)}document.getElementById('modeText').textContent='Drawing mode — click the plot boundary.';refresh()};document.getElementById('finishBtn').onclick=finish;document.getElementById('clearBtn').onclick=()=>{points=[];finished=false;drawing=false;localStorage.removeItem('ramani-majengo-plot');for(let i=0;i<80;i++){if(map.getLayer('p'+i))map.removeLayer('p'+i);if(map.getSource('p'+i))map.removeSource('p'+i)}document.getElementById('modeText').textContent='Map ready.';refresh()};document.getElementById('exportBtn').onclick=()=>{if(points.length<3){alert('Draw a plot first.');return}let data={type:'FeatureCollection',features:[{type:'Feature',properties:{source:'Ramani Majengo',type:'survey_plot'},geometry:{type:'Polygon',coordinates:[[...points,points[0]]]}}]};let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/geo+json'}));a.download='ramani-majengo-plot.geojson';a.click()};if('gpu'in navigator)navigator.gpu.requestAdapter().then(a=>document.getElementById('gpuStatus').textContent=a?'WebGPU adapter detected — ready for future 3D engine.':'WebGPU unavailable; WebGL remains active.').catch(()=>document.getElementById('gpuStatus').textContent='WebGPU unavailable; WebGL remains active.');else document.getElementById('gpuStatus').textContent='WebGPU not exposed by this browser; WebGL remains active.';</script></body></html>